public class Main {
    static int[] parent;

    static int find(int x) {
        if (parent[x] != _____)
            parent[x] = find(parent[x]);  // 경로 압축
        return parent[_____];
    }
    static void union(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra != rb) parent[_____] = ra;
    }
    public static void main(String[] args) {
        int n = 5;
        parent = new int[n + 1];
        for (int i = 0; i <= n; i++) parent[i] = _____;
        union(1, 2); union(2, 3); union(4, 5);
        System.out.println(find(1) == find(_____));  // true
        System.out.println(find(1) == find(4));      // false
        System.out.println(find(4) == find(_____));  // true
    }
}
